extends Node
var p
func _ready() -> void:
	p = get_meta("viento_project")
	_probe()
func _snapshot(label: String, details: Dictionary = {}) -> void:
	var host = p.host.get_ref()
	print("VIENTO_BUDGET_SNAPSHOT:" + JSON.stringify({"label": label, "used": host.execution_budget.snapshot(), "details": details}))
func _probe() -> void:
	var host = p.host.get_ref()
	var first = p.subscribe_event("same", _receive)
	var duplicate = p.subscribe_event("same", _receive)
	var changed = p.write_state("score", 7)
	var unchanged = p.write_state("score", 7.0)
	var missing = p.erase_state("missing")
	_snapshot("no-ops", {"first": first, "duplicate": duplicate, "changed": changed, "unchanged": unchanged, "missing": missing})
func _receive(_value) -> bool:
	return true
